{{pins}}
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 screen(128, 64, &Wire, -1);

// Most soil sensors read HIGHER when the soil is DRIER.
// Put your sensor in dry soil and in water, and write the numbers here.
const int DRY = 900;
const int WET = 300;

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);
  if (!screen.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("Screen not found: check the wiring.");
  }
  screen.setTextColor(SSD1306_WHITE);
}

void loop() {
  int soil = analogRead(SOIL_PIN);
  int wetness = map(soil, DRY, WET, 0, 100);  // as a percentage
  wetness = constrain(wetness, 0, 100);

  screen.clearDisplay();
  screen.setTextSize(1);
  screen.setCursor(0, 0);
  screen.println("Plant buddy");
  screen.setTextSize(2);
  screen.setCursor(0, 20);
  screen.print(wetness);
  screen.println(" % wet");
  if (wetness < 30) {
    screen.println("Water me!");
    digitalWrite(LED_PIN, HIGH);
  } else {
    screen.println("Happy :)");
    digitalWrite(LED_PIN, LOW);
  }
  screen.display();
  delay(1000);
}
